import { validPin, invitationURL, invitationQR } from './invitation.js';
import { createGameClient, remainingSeconds } from './game-client.js';
import * as experience from './experience.js';
const $=id=>document.getElementById(id), app=$('app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search);
let mode=params.get('view')||'player', client, watcher, library=[], selected=new Set(), draft=null, room=null, state=null, offset=0, stateKey='', pending=false, lockedPosition=null;
const teacherMode=()=>mode==='teacher'||mode==='projector';
const button=(text,id,cls='secondary')=>`<button id="${id}" class="${cls}">${text}</button>`;
function notice(message,error=false){$('notice').textContent=message;$('notice').className=error?'error':'';$('notice').hidden=false;clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('notice').hidden=true,7000);}
function connection(text){$('connection').textContent=text;}
function errorText(e){const m=e?.message||String(e);return ({'Invalid login credentials':'E-mail ou senha incorretos.','Email not confirmed':'Confirme seu e-mail antes de entrar.','Anonymous sign-ins are disabled':'A entrada das duplas ainda não está liberada.','Failed to fetch':'Sem comunicação com o servidor. Tentando reconectar…','User already registered':'Esta conta já existe. Use Entrar.'})[m]||m;}
async function run(fn){try{await fn();}catch(e){notice(errorText(e),true);}}
function on(id,fn){$(id)?.addEventListener('click',()=>run(fn));}
function navigate(view){watcher?.stop();watcher=null;room=null;state=null;stateKey='';mode=view;location.href=`?view=${encodeURIComponent(view)}`;}
function nav(active){return `<nav class="tabs" aria-label="Painel da professora">${['Preparar partida','Questionários','Histórico'].map((t,i)=>button(t,['prepareTab','libraryTab','historyTab'][i],active===i?'active':'secondary')).join('')}${button('Sair','logout','plain')}</nav>`;}
function wireNav(){on('prepareTab',showPrepare);on('libraryTab',showLibrary);on('historyTab',showHistory);on('logout',async()=>{watcher?.stop();await client.db.auth.signOut();showLogin();});}
function stopRoom(){watcher?.stop();watcher=null;room=null;state=null;stateKey='';pending=false;lockedPosition=null;}
function showJoin(){stopRoom();connection(navigator.onLine?'Pronto para entrar':'Sem internet');app.innerHTML=`<section class="hero"><div><span class="eyebrow">Conhecimento em equipe</span><h1>Sua dupla.<br>Um desafio incrível!</h1><p>Conversem, raciocinem e enfrentem os desafios de Radiologia juntos.</p><div class="callout">Um celular por dupla. Seu nome, pontuação e posição ficam disponíveis durante a competição.</div><div class="top-space"><a class="button plain" href="?view=teacher">Sou professora</a></div>${experience.card()}</div><section class="panel"><h2>Entrar na competição</h2><form id="joinForm" class="stack"><label>PIN da sala<input name="pin" inputmode="numeric" autocomplete="off" pattern="[0-9]{6}" maxlength="6" required class="pin-input" placeholder="000000" aria-label="PIN da sala"></label><label>Nome da dupla<input name="team_name" minlength="2" maxlength="32" required placeholder="Ex.: Os Fótons"></label><div class="grid"><label>Integrante 1<input name="member_one" maxlength="60" required autocomplete="given-name"></label><label>Integrante 2<input name="member_two" maxlength="60" required autocomplete="off"></label></div><small>Use os nomes pelos quais a professora identifica vocês. Evite dados pessoais desnecessários.</small><button class="full" type="submit">Entrar na sala</button></form><div id="resume" hidden class="top-space"></div></section></section><aside class="promo-ribbon"><a href="#joinForm" aria-label="Jogar RADIOQUIZ"><img src="assets/radioquiz-banner-alegre.webp" alt="Professora Patrícia com roupa florida e mascote do RADIOQUIZ, convidando para jogar" width="1671" height="941" loading="lazy"></a><div><span class="eyebrow">A TURMA ESTÁ CONVIDADA</span><h2>Transforme sua aula em um desafio.</h2><p>Conhecimento, estratégia e muita conversa em dupla.</p><a class="button" href="assets/radioquiz-banner-alegre.webp" download="RADIOQUIZ-banner.webp">Baixar imagem de divulgação</a></div></aside>`;
 const invitedPin=params.get('pin');if(validPin(invitedPin)){$('joinForm').elements.pin.value=invitedPin;$('joinForm').elements.team_name.focus();}
 const saved=localStorage.getItem('radioquiz-player-room');if(saved){$('resume').hidden=false;$('resume').innerHTML=button('Retomar minha última sala','resumeRoom');on('resumeRoom',async()=>{await client.ensurePlayer();await enterRoom(saved);});}
 $('joinForm').addEventListener('submit',e=>{e.preventDefault();run(async()=>{const submit=e.target.querySelector('button');submit.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));await client.ensurePlayer();const result=await client.rpc('join',data);localStorage.setItem('radioquiz-player-room',result.room_id);await enterRoom(result.room_id);try{await client.rpc('set_mascot',{room_id:result.room_id,look:experience.getLook()});await syncRoom();}catch{/* Appearance can remain local until the optional mascot migration is applied. */}}finally{submit.disabled=false;}});});
}
function showLogin(){stopRoom();connection('Acesso da professora');app.innerHTML=`<section class="hero"><div><span class="eyebrow">Painel da professora</span><h1>Sua aula.<br>Um novo desafio.</h1><p>Prepare questionários, acompanhe as duplas e conduza a competição.</p><a class="button plain" href="./">Entrada dos alunos</a>${experience.card('O próximo desafio começa com você')}</div><section class="panel"><h2>Acessar o painel</h2><p class="muted">Receba um link no seu e-mail para entrar. Não precisa lembrar senha.</p><form id="loginForm" class="stack"><label>E-mail da professora<input type="email" name="email" required autocomplete="username"></label><button type="submit">Receber link de acesso</button><button type="button" id="passwordToggle" class="plain">Prefiro entrar com senha</button><div id="passwordArea" class="stack" hidden><label>Senha<input type="password" name="password" autocomplete="current-password"></label><button type="button" id="passwordLogin" class="secondary">Entrar com senha</button></div></form><p id="authMessage" class="callout" hidden></p><small>Use o e-mail autorizado da professora. As duplas entram pelo PIN, sem e-mail.</small></section></section>`;
 async function auth(usePassword){const form=$('loginForm');const email=form.elements.email;if(!email.reportValidity())return;const data=Object.fromEntries(new FormData(form));if(usePassword&&!data.password)throw new Error('Digite sua senha ou use o link por e-mail.');for(const b of form.querySelectorAll('button'))b.disabled=true;try{const result=usePassword?await client.db.auth.signInWithPassword(data):await client.db.auth.signInWithOtp({email:data.email,options:{emailRedirectTo:new URL('?view=teacher',location.href).href,shouldCreateUser:true}});if(result.error)throw result.error;if(!usePassword){$('authMessage').hidden=false;$('authMessage').textContent='Confira sua caixa de entrada e a pasta de spam. Abra o link enviado para acessar o RADIOQUIZ. Por segurança, use o link mais recente.';return;}const identity=await client.rpc('identity');if(!identity.teacher){await client.db.auth.signOut();throw new Error('Este e-mail não tem autorização de professora.');}await showPrepare();}finally{for(const b of form.querySelectorAll('button'))b.disabled=false;}}
 $('loginForm').addEventListener('submit',e=>{e.preventDefault();run(()=>auth(false));});on('passwordToggle',()=>{$('passwordArea').hidden=!$('passwordArea').hidden;});on('passwordLogin',()=>auth(true));
}
async function loadLibrary(){library=await client.rpc('library');connection('Conectado ao RADIOQUIZ');return library;}
function selectedQuestions(){return library.flatMap(q=>q.questions.filter(x=>selected.has(x.id)));}
async function showPrepare(){stopRoom();await loadLibrary();app.innerHTML=nav(0)+`<div class="heading-actions"><span class="eyebrow">Antes de começar</span><h1>Prepare sua competição</h1><p class="muted">Combine questionários e marque exatamente as perguntas desta partida.</p></div><section class="panel stack"><div class="grid"><label>Nome da sala<input id="roomTitle" value="Desafio de Radiologia" minlength="3" maxlength="120"></label><label>Disciplina / filtro<input id="filter" placeholder="Busque título ou disciplina"></label></div><div class="grid"><label>Tempo por pergunta<select id="roomTime"><option value="">Usar tempo de cada pergunta</option><option value="15">15 segundos</option><option value="30">30 segundos</option><option value="45">45 segundos</option><option value="60">60 segundos</option><option value="90">90 segundos</option><option value="120">120 segundos</option><option value="180">180 segundos</option></select></label><label>Pontos por acerto<select id="roomPoints"><option value="">Usar pontos de cada pergunta</option><option value="500">Até 500 pontos</option><option value="1000">Até 1.000 pontos</option><option value="2000">Até 2.000 pontos</option></select></label></div><label>Penalidade por erro (0 = sem penalidade)<input id="penalty" type="number" value="0" min="0" max="10000" step="10"></label><small>O acerto vale de 50% a 100% dos pontos, conforme o tempo de resposta. A pontuação é calculada no servidor.</small><div id="quizSelection" class="cards"></div></section><div class="selected-summary between"><span><b id="selectedCount">0 perguntas</b><br><small id="selectedTitles">Nenhum questionário selecionado</small></span><button id="createRoom" disabled>Criar sala e gerar PIN</button></div>`;wireNav();
 function renderSelection(){const filter=$('filter').value.toLocaleLowerCase('pt-BR');const quizzes=library.filter(q=>(q.title+' '+q.subject).toLocaleLowerCase('pt-BR').includes(filter));$('quizSelection').innerHTML=quizzes.length?quizzes.map(q=>`<article class="quiz"><div class="between"><div><h3>${esc(q.title)}</h3><span class="tag">${esc(q.subject)} · ${q.questions.length} perguntas</span></div><button class="plain" data-all="${q.id}">Marcar / desmarcar todas</button></div><ul class="questions">${q.questions.map(x=>`<li><label class="question-select"><input type="checkbox" data-question="${x.id}" ${selected.has(x.id)?'checked':''}><span><b>${x.position}.</b> ${esc(x.prompt)}<br><small>${x.time_limit_seconds}s · ${x.points} pontos${x.topic?' · '+esc(x.topic):''}</small></span></label></li>`).join('')}</ul></article>`).join(''):`<div class="empty"><h3>${library.length?'Nenhum resultado':'Sua biblioteca está vazia'}</h3><p>Cadastre um questionário para preparar a primeira competição.</p>${button('Abrir biblioteca','emptyLibrary')}</div>`;
 on('emptyLibrary',showLibrary);document.querySelectorAll('[data-question]').forEach(el=>el.addEventListener('change',()=>{el.checked?selected.add(el.dataset.question):selected.delete(el.dataset.question);updateSummary();}));document.querySelectorAll('[data-all]').forEach(el=>el.addEventListener('click',()=>{const q=library.find(x=>x.id===el.dataset.all),all=q.questions.every(x=>selected.has(x.id));q.questions.forEach(x=>all?selected.delete(x.id):selected.add(x.id));renderSelection();updateSummary();}));}
 function updateSummary(){const qs=selectedQuestions();$('selectedCount').textContent=`${qs.length} pergunta${qs.length===1?'':'s'} selecionada${qs.length===1?'':'s'}`;$('selectedTitles').textContent=library.filter(q=>q.questions.some(x=>selected.has(x.id))).map(q=>q.title).join(' + ')||'Nenhum questionário selecionado';$('createRoom').disabled=qs.length===0||qs.length>100;}
 $('filter').addEventListener('input',renderSelection);renderSelection();updateSummary();
 on('createRoom',async()=>{const data={title:$('roomTitle').value.trim(),question_ids:selectedQuestions().map(q=>q.id),wrong_penalty:Number($('penalty').value)};if(data.title.length<3)throw new Error('Dê um nome de pelo menos três letras para a sala.');if($('roomTime').value)data.time_limit_seconds=Number($('roomTime').value);if($('roomPoints').value)data.points=Number($('roomPoints').value);$('createRoom').disabled=true;try{const result=await client.rpc('create_room',data);localStorage.setItem(`radioquiz-pin-${result.room_id}`,result.pin);localStorage.setItem(`radioquiz-source-${result.room_id}`,JSON.stringify(data));await enterRoom(result.room_id);}finally{if($('createRoom'))$('createRoom').disabled=false;}});
}
async function showLibrary(){stopRoom();await loadLibrary();app.innerHTML=nav(1)+`<div class="between heading-actions"><div><span class="eyebrow">Biblioteca da professora</span><h1>Questionários</h1></div><div class="row">${button('Novo questionário','newQuiz','')}${button('Importar JSON','importQuiz','plain')}${button('Publicar bancos faltantes (12 disciplinas)','publishAllBanks','secondary')}${button('Atualizar Física e Proteção (30 cada)','replacePhysics','secondary')}${button('Carregar Proteção Radiológica (30)','loadProtection','secondary')}${button('Carregar Mamografia (30)','loadMamografia','secondary')}${button('Carregar Tomografia (30)','loadTomografia','secondary')}${button('Carregar Radiologia Industrial (30)','loadIndustrial','secondary')}${button('Carregar Formação da Imagem (30)','loadFormacao','secondary')}${button('Carregar Física das Radiações (30)','loadFisica','secondary')}<input type="file" id="importFile" accept="application/json,.json" hidden></div></div><div class="cards">${library.length?library.map(q=>`<article class="panel between"><div><h2>${esc(q.title)}</h2><span class="tag">${esc(q.subject)}</span><p class="muted">${q.questions.length} perguntas</p></div><div class="row"><button data-edit="${q.id}" class="secondary">Editar</button><button data-export="${q.id}" class="plain">Exportar</button><button data-delete="${q.id}" class="danger">Excluir</button></div></article>`).join(''):'<div class="panel empty"><h2>Seu primeiro questionário começa aqui</h2><p>Crie as perguntas com quatro alternativas, gabarito e explicação.</p></div>'}</div>`;wireNav();on('newQuiz',()=>editQuiz());on('importQuiz',()=>$('importFile').click());on('replacePhysics',()=>run(async()=>{if(!confirm('Atualizar Física das Radiações e Proteção Radiológica na biblioteca com os bancos novos de 30 questões, substituindo apenas as versões anteriores dessas disciplinas?'))return;const targets=[['fisica-das-radiacoes','Física das Radiações'],['protecao-radiologica','Proteção Radiológica']];let saved=[];for(const [slug,subject] of targets){const response=await fetch('./bancos/'+slug+'-radioquiz-30.json',{cache:'no-store'});if(!response.ok)throw Error('Arquivo indisponível: '+subject);const data=await response.json();if(!Array.isArray(data.questions)||data.questions.length!==30||data.questions.some(q=>!Array.isArray(q.options)||q.options.length!==4||!Number.isInteger(q.answer_index)||q.answer_index<0||q.answer_index>3))throw Error('Banco inválido: '+subject);const matches=library.filter(q=>q.subject.trim().toLocaleLowerCase('pt-BR')===subject.toLocaleLowerCase('pt-BR'));if(matches.length>1)throw Error('Há mais de uma versão salva de '+subject+'; escolha a correta antes de substituir.');await client.rpc('save_quiz',{...data,id:matches[0]?.id||null});saved.push(subject);}await showLibrary();notice('Bancos atualizados: '+saved.join(' e ')+'.');}));on('publishAllBanks',()=>run(async()=>{const slugs=['radiologia-digital','radiologia-veterinaria','radiologia-odontologica','medicina-nuclear','densitometria-ossea','radioterapia','mamografia','tomografia','radiologia-industrial','formacao-da-imagem','protecao-radiologica','fisica-das-radiacoes'];if(!confirm('Importar para o banco do RADIOQUIZ os questionários ainda ausentes? Os já existentes serão preservados.'))return;const btn=$('publishAllBanks');btn.disabled=true;let saved=0,skipped=0,errors=[];try{for(const slug of slugs){try{const response=await fetch('./bancos/'+slug+'-radioquiz-30.json',{cache:'no-store'});if(!response.ok)throw Error('arquivo HTTP '+response.status);const data=await response.json();if(!Array.isArray(data.questions)||data.questions.length!==30)throw Error('quantidade diferente de 30');if(data.questions.some(q=>!Array.isArray(q.options)||q.options.length!==4||new Set(q.options.map(v=>String(v).trim().toLowerCase())).size!==4||!Number.isInteger(q.answer_index)||q.answer_index<0||q.answer_index>3))throw Error('alternativas ou gabarito inválidos');if(library.some(q=>q.subject.trim().toLocaleLowerCase('pt-BR')===data.subject.trim().toLocaleLowerCase('pt-BR'))){skipped++;continue;}await client.rpc('save_quiz',{...data,id:null});saved++;}catch(e){errors.push(slug+': '+(e.message||e));}}await showLibrary();notice('Importados: '+saved+'; já existentes: '+skipped+'; falhas: '+errors.length+(errors.length?' — '+errors.join(' | '):''),errors.length>0);}finally{const b=$('publishAllBanks');if(b)b.disabled=false;}}));for(const [id,slug] of [['loadMamografia','mamografia'],['loadTomografia','tomografia'],['loadIndustrial','radiologia-industrial'],['loadFormacao','formacao-da-imagem'],['loadFisica','fisica-das-radiacoes'],['loadProtection','protecao-radiologica']])on(id,()=>run(async()=>{const response=await fetch('./bancos/'+slug+'-radioquiz-30.json',{cache:'no-store'});if(!response.ok)throw Error('Banco não disponível');const data=await response.json();if(!Array.isArray(data.questions)||data.questions.length!==30)throw Error('Banco incompleto');editQuiz({...data,id:null});}));$('importFile').addEventListener('change',e=>run(async()=>{const file=e.target.files[0];if(!file)return;if(file.size>2_000_000)throw new Error('Use um arquivo de até 2 MB.');const data=JSON.parse(await file.text());if(!Array.isArray(data.questions))throw new Error('O JSON precisa conter título, disciplina e a lista questions.');data.id=null;editQuiz(data);}));
 document.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>editQuiz(library.find(x=>x.id===b.dataset.edit))));document.querySelectorAll('[data-export]').forEach(b=>b.addEventListener('click',()=>download(`radioquiz-questionario.json`,JSON.stringify(library.find(x=>x.id===b.dataset.export),null,2),'application/json')));document.querySelectorAll('[data-delete]').forEach(b=>b.addEventListener('click',()=>{if(confirm('Excluir este questionário? Questionários utilizados em partidas são preservados.'))run(async()=>{await client.rpc('delete_quiz',{id:b.dataset.delete});await showLibrary();});}));
}
const blankQuestion=()=>({prompt:'',options:['','','',''],answer_index:0,explanation:'',time_limit_seconds:30,points:1000,topic:'',image_url:''});
function editQuiz(quiz){draft=structuredClone(quiz||{title:'',subject:'',questions:[blankQuestion()]});app.innerHTML=nav(1)+`<div class="between heading-actions"><h1>${draft.id?'Editar questionário':'Novo questionário'}</h1>${button('Voltar à biblioteca','cancelEdit','plain')}</div><form id="quizForm" class="stack"><section class="panel grid"><label>Título<input name="title" minlength="3" maxlength="120" required value="${esc(draft.title)}"></label><label>Disciplina<input name="subject" minlength="2" maxlength="80" required value="${esc(draft.subject)}" list="subjects"></label><datalist id="subjects">${['Física das Radiações','Proteção Radiológica','Anatomia Radiológica','Radiologia Digital','Radiologia Odontológica','Radiologia Veterinária','Tomografia Computadorizada','Ressonância Magnética','Mamografia','Medicina Nuclear','Radioterapia','Processamento Radiográfico','Densitometria Óssea'].map(s=>`<option value="${s}">`).join('')}</datalist></section><div id="questionEditor" class="stack"></div><div class="row">${button('Adicionar pergunta','addQuestion','secondary')}<button type="submit">Salvar questionário</button></div><p class="callout">Revise os gabaritos antes de usar em aula. Ao editar um questionário já usado, o sistema cria uma nova versão e preserva o histórico.</p></form>`;wireNav();on('cancelEdit',showLibrary);
 function renderQuestions(){$('questionEditor').innerHTML=draft.questions.map((q,i)=>`<section class="question-block"><div class="between"><h2>Pergunta ${i+1}</h2><button type="button" data-remove="${i}" class="danger" ${draft.questions.length===1?'disabled':''}>Remover</button></div><div class="stack"><label>Enunciado<textarea data-field="prompt" data-i="${i}" minlength="5" maxlength="1500" required>${esc(q.prompt)}</textarea></label><div class="grid">${q.options.map((option,j)=>`<label>Alternativa ${'ABCD'[j]}<input data-option="${j}" data-i="${i}" maxlength="500" required value="${esc(option)}"></label>`).join('')}</div><div class="grid"><label>Resposta correta<select data-field="answer_index" data-i="${i}">${['A','B','C','D'].map((s,j)=>`<option value="${j}" ${j===q.answer_index?'selected':''}>${s}</option>`).join('')}</select></label><label>Assunto<input data-field="topic" data-i="${i}" maxlength="120" value="${esc(q.topic)}"></label></div><label>Explicação<textarea data-field="explanation" data-i="${i}" maxlength="1500">${esc(q.explanation)}</textarea></label><div class="grid"><label>Tempo (10 a 180 segundos)<input data-field="time_limit_seconds" data-i="${i}" type="number" min="10" max="180" required value="${q.time_limit_seconds}"></label><label>Pontos (10 a 10.000)<input data-field="points" data-i="${i}" type="number" min="10" max="10000" required value="${q.points}"></label></div><label>Imagem opcional: endereço HTTPS<input data-field="image_url" data-i="${i}" type="url" placeholder="https://…" value="${esc(q.image_url)}"></label></div></section>`).join('');document.querySelectorAll('[data-field]').forEach(el=>el.addEventListener('input',()=>{draft.questions[+el.dataset.i][el.dataset.field]=['answer_index','time_limit_seconds','points'].includes(el.dataset.field)?Number(el.value):el.value;}));document.querySelectorAll('[data-option]').forEach(el=>el.addEventListener('input',()=>draft.questions[+el.dataset.i].options[+el.dataset.option]=el.value));document.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{draft.questions.splice(+b.dataset.remove,1);renderQuestions();}));}
 renderQuestions();$('addQuestion').type='button';on('addQuestion',()=>{if(draft.questions.length>=200)throw new Error('Limite de 200 perguntas por questionário.');draft.questions.push(blankQuestion());renderQuestions();$('questionEditor').lastElementChild.scrollIntoView({behavior:'smooth',block:'start'});});
 $('quizForm').addEventListener('submit',e=>{e.preventDefault();run(async()=>{const data=new FormData(e.target);draft.title=data.get('title').trim();draft.subject=data.get('subject').trim();if(draft.questions.some(q=>q.image_url&&!q.image_url.startsWith('https://')))throw new Error('As imagens precisam usar um endereço HTTPS.');const b=e.target.querySelector('[type=submit]');b.disabled=true;try{await client.rpc('save_quiz',draft);notice('Questionário salvo.');selected.clear();await showLibrary();}finally{b.disabled=false;}});});
}
async function showHistory(){stopRoom();const rooms=await client.rpc('history');app.innerHTML=nav(2)+`<span class="eyebrow">Suas competições</span><h1>Histórico e salas abertas</h1><div class="cards">${rooms.length?rooms.map(r=>`<article class="panel between"><div><h2>${esc(r.title)}</h2><span class="tag">${({lobby:'Recebendo duplas',question:'Pergunta em andamento',result:'Resultado da pergunta',finished:'Encerrada'})[r.phase]}</span><p class="muted">${new Date(r.created_at).toLocaleString('pt-BR')} · ${r.current_position} pergunta(s) iniciada(s)</p></div><button data-room="${r.id}">Abrir ${r.phase==='finished'?'resultado':'sala'}</button></article>`).join(''):'<section class="panel empty">As competições aparecerão aqui.</section>'}</div>`;wireNav();document.querySelectorAll('[data-room]').forEach(b=>b.addEventListener('click',()=>run(()=>enterRoom(b.dataset.room))));}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function enterRoom(id){stopRoom();room=id;stateKey='';if(teacherMode()&&mode!=='projector')localStorage.setItem('radioquiz-teacher-room',id);app.innerHTML='<section class="panel empty">Buscando o estado da sala…</section>';await syncRoom();watcher=client.watch(room,syncRoom,status=>{if(status!=='SUBSCRIBED')connection('Sincronizando pelo servidor…');});}
async function syncRoom(){if(!room)return;const id=room,start=Date.now();try{const next=await client.rpc('state',{room_id:id,projection:mode==='projector'});if(room!==id)return;offset=Date.parse(next.server_now)-(start+Date.now())/2;state=next;connection('Conectado · estado sincronizado');const key=JSON.stringify({...next,server_now:undefined});if(key!==stateKey){stateKey=key;if(next.phase!=='question'||next.answer)lockedPosition=null;renderRoom();}updateClock();}catch(e){connection(navigator.onLine?'Reconectando ao servidor…':'Sem internet · aguardando conexão');if(/sessão não pode|Sala não encontrada|bloqueada/i.test(e.message)){watcher?.stop();app.innerHTML=`<section class="panel empty"><h2>Acesso à sala indisponível</h2><p>${esc(e.message)}</p>${button('Voltar','leaveRoom')}</section>`;on('leaveRoom',()=>teacherMode()?showHistory():showJoin());}throw e;}}
function rankingHTML(s){return `<div class="table-scroll"><table><thead><tr><th>Posição</th><th>Dupla</th><th>Pontos</th></tr></thead><tbody>${(s.ranking||[]).map(t=>`<tr class="${t.id===s.team_id?'me':''}"><td>${t.rank}º</td><td>${experience.badge(t.mascot,t.team_name)}${esc(t.team_name)}</td><td>${t.score.toLocaleString('pt-BR')}</td></tr>`).join('')}</tbody></table></div>`;}
function renderRoom(){const s=state,host=mode==='teacher',projector=mode==='projector',q=s.question;document.body.classList.toggle('projector',projector);const pin=localStorage.getItem(`radioquiz-pin-${room}`)||'';const invite=invitationURL(location.href,pin);
 app.innerHTML=`${host?`<div class="between heading-actions"><button id="backHistory" class="plain">← Minhas salas</button><div class="row"><a class="button secondary" target="_blank" rel="noopener" href="?view=projector&room=${room}">Abrir tela do projetor</a>${button('Encerrar competição','finishRoom','danger')}</div></div>`:''}<div class="between"><div><span class="eyebrow">${projector?'Tela da competição':host?'Controle da professora':esc(s.team_name)}</span><h2>${esc(s.title)}</h2></div><span class="tag">${s.team_count} dupla(s) · ${s.position}/${s.total} perguntas</span></div>${s.phase==='lobby'?`<section class="panel empty top-space"><span class="eyebrow">${host||projector?'A turma entra pelo PIN':'Tudo pronto'}</span><h1>${host||projector?'Vamos começar?':'Sua dupla está na sala!'}</h1>${host||projector?`<div class="pin">${pin||'PIN nesta sessão indisponível'}</div><p>Abra a câmera do celular e aponte para o QR Code.<br>Ou acesse <b>${esc(location.origin+location.pathname)}</b> e digite o PIN.<br>Um aparelho por dupla.</p>${invite?`<div class="room-invitation"><div class="room-qr">${invitationQR(invite)}</div><div class="stack"><label>Link para as duplas<input id="invitationLink" readonly value="${esc(invite)}" aria-label="Link de entrada da sala"></label>${button('Copiar link da sala','copyInvitation','secondary')}<p id="invitationStatus" role="status" class="muted"></p></div></div>`:'<p class="muted">Abra esta sala no navegador em que o PIN foi gerado para compartilhar o convite.</p>'}`:'<p>Aguardem a professora iniciar a competição.</p>'}${host?button('Iniciar competição','nextQuestion',''):''}${projector||!host?experience.card(projector?'A energia da turma está aqui':'Seu mascote está pronto!'):''}</section>`:''}${q&&s.phase!=='lobby'?`<section class="panel top-space"><div class="between"><span class="tag">Pergunta ${s.position} de ${s.total}</span><span id="timer" class="timer" aria-label="Segundos restantes"></span>${!host&&!projector?experience.mini():''}</div><div class="progress"><div id="timeBar"></div></div><h1 class="question-title">${esc(q.prompt)}</h1>${q.image_url&&/^https:\/\//.test(q.image_url)?`<img class="question-image" src="${esc(q.image_url)}" alt="Imagem de apoio da pergunta" referrerpolicy="no-referrer">`:''}<div class="options">${q.options.map((option,i)=>`<button class="option ${s.answer?.selected_index===i?'selected':''} ${s.phase!=='question'&&q.answer_index===i?'correct':''} ${s.phase!=='question'&&s.answer?.selected_index===i&&q.answer_index!==i?'incorrect':''}" data-answer="${i}" ${host||projector||s.phase!=='question'||s.answer||pending||lockedPosition===s.position?'disabled':''}><b>${'ABCD'[i]}</b><span>${esc(option)}</span></button>`).join('')}</div><div class="between"><p id="answerStatus" role="status">${host||projector?`${s.answer_count} de ${s.team_count} duplas responderam`:s.answer?(s.phase==='question'?'Resposta registrada. Aguarde o resultado.':'Resposta registrada nesta pergunta.'):s.phase==='question'?'Conversem e escolham uma alternativa.':'Sua dupla não respondeu a esta pergunta.'}</p>${host?(s.phase==='question'?button('Encerrar pergunta','closeQuestion',''):s.phase==='result'?button(s.position===s.total?'Finalizar competição':'Próxima pergunta','nextQuestion',''):''):''}</div>${s.phase!=='question'?`<div class="callout success"><b>Resposta correta: ${'ABCD'[q.answer_index]}</b>${q.explanation?`<p>${esc(q.explanation)}</p>`:''}${s.answer?`<b>${s.answer.is_correct?'Acertaram!':'Não foi desta vez.'} ${s.answer.awarded_points>0?'+':''}${s.answer.awarded_points} pontos nesta pergunta.</b>`:''}</div>`:''}</section>`:''}${s.phase==='finished'?`<section class="panel empty top-space"><span class="eyebrow">Competição encerrada</span><h1>Conhecimento que fica.</h1><p>${projector?'Confiram os resultados nos celulares.':'Obrigado por participar do desafio!'}</p>${host?`<div class="row">${button('Exportar resultados','exportResults','secondary')}${button('Preparar outra partida','newGame','')}${localStorage.getItem(`radioquiz-source-${room}`)?button('Repetir esta partida','restartRoom','plain'):''}</div>`:!projector?button('Entrar em outra sala','leaveRoom','secondary'):''}</section>`:''}${!host&&!projector?`<section class="stats top-space">${(()=>{const me=s.ranking?.find(x=>x.id===s.team_id);return `<div class="stat"><small>Pontuação da dupla</small><strong>${me?.score??0}</strong></div><div class="stat"><small>Classificação</small><strong>${me?me.rank+'º':'—'}</strong></div>`;})()}</section>`:''}${host?`<section class="grid top-space"><article class="panel"><h2>Duplas participantes</h2>${(s.teams||[]).map(t=>`<div class="team ${t.blocked?'blocked':''}"><div>${experience.badge(t.mascot,t.team_name)}<span class="team-names"><b>${esc(t.team_name)}</b><small><span>${esc(t.member_one)} + ${esc(t.member_two)}</span>${t.blocked?'Bloqueada':''}</small></span></div><button class="${t.blocked?'secondary':'danger'}" data-block="${t.id}" data-blocked="${t.blocked}">${t.blocked?'Liberar':'Bloquear'}</button></div>`).join('')||'<p class="muted">Aguardando as duplas entrarem…</p>'}</article><article class="panel"><h2>Classificação</h2>${rankingHTML(s)}</article></section>`:!projector&&s.phase!=='lobby'?`<section class="panel top-space"><h2>Classificação da competição</h2>${rankingHTML(s)}</section>`:''}`;
 on('copyInvitation',async()=>{try{await navigator.clipboard.writeText(invite);$('invitationStatus').textContent='Link copiado! Envie para as duplas.';}catch{$('invitationLink').focus();$('invitationLink').select();$('invitationStatus').textContent='Selecionei o link. Use Copiar no seu aparelho.';}});on('backHistory',showHistory);on('newGame',showPrepare);on('leaveRoom',showJoin);on('nextQuestion',()=>control('next'));on('closeQuestion',()=>control('close'));on('finishRoom',async()=>{if(confirm('Encerrar esta competição agora? Os resultados ficarão no histórico.'))await control('finish');});on('restartRoom',async()=>{if(confirm('Abrir uma nova sala com as mesmas perguntas? A competição anterior ficará preservada.')){const source=JSON.parse(localStorage.getItem(`radioquiz-source-${room}`));if(!source)throw new Error('Prepare a nova partida pela biblioteca.');const result=await client.rpc('create_room',source);localStorage.setItem(`radioquiz-pin-${result.room_id}`,result.pin);localStorage.setItem(`radioquiz-source-${result.room_id}`,JSON.stringify(source));await enterRoom(result.room_id);}});on('exportResults',()=>download('radioquiz-resultados.json',JSON.stringify(s,null,2),'application/json'));document.querySelectorAll('[data-block]').forEach(b=>b.addEventListener('click',()=>run(async()=>{await client.rpc('block',{room_id:room,team_id:b.dataset.block,blocked:b.dataset.blocked!=='true'});await syncRoom();})));
 document.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>run(async()=>{if(pending||lockedPosition===s.position)return;pending=true;lockedPosition=s.position;renderRoom();try{const result=await client.rpc('answer',{room_id:room,position:s.position,selected_index:Number(b.dataset.answer)});notice(result.accepted?'Resposta registrada.':result.reason,!result.accepted);}finally{pending=false;try{await syncRoom();if(!state.answer){lockedPosition=null;renderRoom();}}catch{notice('Não foi possível confirmar a resposta. Ao reconectar, conferiremos o registro no servidor.',true);}}})));
 experience.reactToState(s,mode);updateClock();}
async function control(action){if(pending)return;pending=true;document.querySelectorAll('#nextQuestion,#closeQuestion,#finishRoom').forEach(b=>b.disabled=true);try{await client.rpc('control',{room_id:room,action});await syncRoom();}finally{pending=false;}}
let deadlineSync=0;
function updateClock(){if(!state)return;const seconds=remainingSeconds(state,offset);if($('timer'))$('timer').textContent=state.phase==='question'?seconds+'s':'Encerrada';if($('timeBar'))$('timeBar').style.width=(state.phase==='question'?seconds/(state.question?.time_limit_seconds||30)*100:0)+'%';if(state.phase==='question'&&seconds===0){document.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);if(Date.now()-deadlineSync>1500){deadlineSync=Date.now();syncRoom().catch(()=>{});}}}
setInterval(updateClock,250);
window.addEventListener('offline',()=>connection('Sem internet · aguardando reconexão'));
async function start(){experience.initExperience(async look=>{if(!room||teacherMode())return false;try{await client.rpc('set_mascot',{room_id:room,look});await syncRoom();return true;}catch{return false;}});if(!['player','teacher','projector'].includes(mode))mode='player';client=createGameClient(teacherMode()?'teacher':'player');if(!teacherMode()){showJoin();return;}const {data:{session},error}=await client.db.auth.getSession();if(error)throw error;if(!session){showLogin();return;}const identity=await client.rpc('identity');if(!identity.teacher){showLogin();notice('Entre com a conta autorizada da professora.',true);return;}if(mode==='projector'){const id=params.get('room');if(id)await enterRoom(id);else app.innerHTML='<section class="panel">Abra a projeção pelo painel de uma sala.</section>';}else await showPrepare();}
start().catch(e=>{connection('Falha de conexão');app.innerHTML=`<section class="panel empty"><h1>Não foi possível conectar</h1><p>${esc(errorText(e))}</p><button id="retry">Tentar novamente</button></section>`;on('retry',()=>location.reload());});
